/**
 * Response types for the three PM features (date range filter, anomaly alerts,
 * B2B vs B2C comparison). Property names and values were verified against the
 * OpenAPI schema generated by the backend (see `api-exploration.md`).
 * Dates travel as `YYYY-MM-DD` strings. This file is a specification only.
 */

/** Direction of a money movement. */
export type OperationType = "income" | "outcome";

/** Business line that owns a movement. */
export type BusinessType = "B2B" | "B2C";

/** Movement category. The mock data only produces `sales` and `others` for income. */
export type Category =
  | "suppliers"
  | "sales"
  | "operational"
  | "administrative"
  | "others";

/** One money movement, as returned by `GET /api/metrics` (and `/api/metrics/b2b`, `/api/metrics/b2c`). */
export interface FinancialMovement {
  /** Date of the movement. Format `YYYY-MM-DD`. */
  create_date: string;
  /** Amount of the movement, always positive. The direction is given by `operation_type`. */
  amount: number;
  /** Whether the movement is money coming in or going out. */
  operation_type: OperationType;
  /** Category of the movement. Income only uses `sales` and `others`. */
  category: Category;
  /** Business line that owns the movement. */
  business_type: BusinessType;
}

/** Response of `GET /api/metrics`. Sorted by `create_date` ascending. An empty array means no movements for the current filters (HTTP 200). */
export type MetricsResponse = FinancialMovement[];

/**
 * Response of `GET /api/metrics/facets`.
 * Values are global: they do not change with business line or date filters.
 */
export interface FacetsResponse {
  /** Operation types present in the dataset. Valid values: `income`, `outcome`. */
  operation_types: OperationType[];
  /** Business lines present in the dataset. Valid values: `B2B`, `B2C`. */
  business_types: BusinessType[];
  /** All categories present in the dataset, for both business lines. */
  categories: Category[];
  /** Oldest movement date in the dataset. Format `YYYY-MM-DD`. Inclusive lower bound for the date filter. */
  min_date: string;
  /** Most recent movement date in the dataset. Format `YYYY-MM-DD`. Inclusive upper bound for the date filter. */
  max_date: string;
}

/**
 * One anomaly row from `GET /api/metrics/alerts`: a period whose outcome rose
 * above the baseline by more than the requested threshold.
 */
export interface AlertEntry {
  /** Period label. Format depends on `group_by`: `YYYY-MM` (month), `YYYY-Www` (week) or `YYYY-MM-DD` (day). */
  period: string;
  /** Total outcome of the period, rounded to 2 decimals. Always positive. */
  outcome_total: number;
  /** Average outcome of ALL earlier periods inside the requested range (not a 3-period moving average), rounded to 2 decimals. Always greater than 0. */
  baseline_average: number;
  /** Relative increase over the baseline as a ratio, rounded to 4 decimals. `0.5` means +50%. Always greater than the requested threshold. Multiply by 100 to show a percentage. */
  increase_ratio: number;
}

/** Response of `GET /api/metrics/alerts`. An empty array means no anomalies for the current filters (HTTP 200). */
export type AlertsResponse = AlertEntry[];

/** One row from `GET /api/metrics/categories/top`. */
export interface CategoryEntry {
  /** Category of the row. Valid values: `suppliers`, `sales`, `operational`, `administrative`, `others`. */
  category: Category;
  /** Operation type that was aggregated. Echoes the `operation_type` query parameter. */
  operation_type: OperationType;
  /** Sum of `amount` for the category, rounded to 2 decimals. Rows come sorted from highest to lowest. The API returns no percentage: compute it from the sum of the rows. */
  total_amount: number;
}

/** Response of `GET /api/metrics/categories/top`. May hold fewer rows than `limit`, or be empty (HTTP 200). */
export type TopCategoriesResponse = CategoryEntry[];
